import React, { useState } from 'react';
import { format } from 'date-fns';
import './Transactions.css';

const CATEGORY_COLORS = {
  Food: '#fb923c', Transport: '#60a5fa', Entertainment: '#a78bfa',
  Shopping: '#f472b6', Health: '#4ade80', Utilities: '#2dd4bf',
  Rent: '#c9a84c', Savings: '#34d399', Other: '#94a3b8',
  Salary: '#4ade80', Freelance: '#60a5fa', Bonus: '#c9a84c',
};
const CAT_ICONS = {
  Food:'🍜',Transport:'🚗',Entertainment:'🎬',Shopping:'🛍',Health:'💊',
  Utilities:'⚡',Rent:'🏠',Savings:'💰',Other:'📦',Salary:'💼',Freelance:'💻',Bonus:'🎁',
};
const EXPENSE_CATS = ['Food','Transport','Entertainment','Shopping','Health','Utilities','Rent','Other'];
const INCOME_CATS = ['Salary','Freelance','Bonus','Other'];

export default function Transactions({ currentTxns, addTransaction, deleteTransaction }) {
  const [showForm, setShowForm] = useState(false);
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [form, setForm] = useState({
    type: 'expense', amount: '', category: 'Food', description: '',
    date: format(new Date(), 'yyyy-MM-dd'),
  });
  const [deleting, setDeleting] = useState(null);

  const fmt = v => `$${Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  const filtered = [...currentTxns]
    .filter(t => {
      if (filter !== 'all' && t.type !== filter) return false;
      if (search && !t.description.toLowerCase().includes(search.toLowerCase()) &&
          !t.category.toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    })
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  const handleSubmit = () => {
    if (!form.amount || !form.description || !form.date) return;
    addTransaction({ ...form, amount: parseFloat(form.amount) });
    setForm({ type: 'expense', amount: '', category: 'Food', description: '', date: format(new Date(), 'yyyy-MM-dd') });
    setShowForm(false);
  };

  const handleDelete = (id) => {
    setDeleting(id);
    setTimeout(() => { deleteTransaction(id); setDeleting(null); }, 300);
  };

  const cats = form.type === 'income' ? INCOME_CATS : EXPENSE_CATS;

  return (
    <div className="transactions-page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Transactions</h1>
          <p className="page-subtitle">{currentTxns.length} transactions this month</p>
        </div>
        <button className="btn-add" onClick={() => setShowForm(v => !v)}>
          <span>{showForm ? '✕ Cancel' : '+ Add Transaction'}</span>
        </button>
      </div>

      {/* Add Form */}
      {showForm && (
        <div className="add-form-card">
          <div className="form-title">New Transaction</div>
          <div className="form-type-toggle">
            {['expense','income'].map(t => (
              <button
                key={t}
                className={`type-btn ${form.type === t ? 'active ' + t : ''}`}
                onClick={() => setForm(f => ({ ...f, type: t, category: t === 'income' ? 'Salary' : 'Food' }))}
              >
                {t === 'expense' ? '↓ Expense' : '↑ Income'}
              </button>
            ))}
          </div>
          <div className="form-grid">
            <div className="form-group">
              <label>Amount</label>
              <input
                type="number" placeholder="0.00" min="0" step="0.01"
                value={form.amount}
                onChange={e => setForm(f => ({ ...f, amount: e.target.value }))}
              />
            </div>
            <div className="form-group">
              <label>Date</label>
              <input type="date" value={form.date} onChange={e => setForm(f => ({ ...f, date: e.target.value }))} />
            </div>
            <div className="form-group">
              <label>Category</label>
              <select value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
                {cats.map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label>Description</label>
              <input type="text" placeholder="What was this for?" value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                onKeyDown={e => e.key === 'Enter' && handleSubmit()}
              />
            </div>
          </div>
          <button className="btn-submit" onClick={handleSubmit}>Add Transaction</button>
        </div>
      )}

      {/* Filters */}
      <div className="filter-row">
        <div className="filter-tabs">
          {['all','expense','income'].map(f => (
            <button key={f} className={`filter-tab ${filter === f ? 'active' : ''}`}
              onClick={() => setFilter(f)}>
              {f === 'all' ? 'All' : f === 'expense' ? 'Expenses' : 'Income'}
            </button>
          ))}
        </div>
        <input
          className="search-input" type="text"
          placeholder="🔍 Search transactions..."
          value={search} onChange={e => setSearch(e.target.value)}
        />
      </div>

      {/* Table */}
      <div className="txn-table-card">
        {filtered.length === 0 ? (
          <div className="empty-state">No transactions found</div>
        ) : (
          <div className="txn-table">
            <div className="table-header">
              <span>Transaction</span>
              <span>Category</span>
              <span>Date</span>
              <span style={{ textAlign: 'right' }}>Amount</span>
              <span></span>
            </div>
            {filtered.map(t => (
              <div
                key={t.id}
                className={`table-row ${deleting === t.id ? 'deleting' : ''}`}
              >
                <div className="row-desc">
                  <div className="row-icon" style={{ background: `${CATEGORY_COLORS[t.category] || '#94a3b8'}20` }}>
                    {CAT_ICONS[t.category] || '📦'}
                  </div>
                  <span className="row-desc-text">{t.description}</span>
                </div>
                <div>
                  <span className="cat-chip" style={{
                    background: `${CATEGORY_COLORS[t.category] || '#94a3b8'}18`,
                    color: CATEGORY_COLORS[t.category] || '#94a3b8',
                  }}>
                    {t.category}
                  </span>
                </div>
                <span className="row-date">{format(new Date(t.date + 'T00:00:00'), 'MMM d, yyyy')}</span>
                <span className={`row-amount ${t.type}`} style={{ textAlign: 'right' }}>
                  {t.type === 'income' ? '+' : '-'}{fmt(t.amount)}
                </span>
                <button className="delete-btn" onClick={() => handleDelete(t.id)} title="Delete">✕</button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
